use std::collections::HashMap;
use std::num::ParseIntError;

fn read_stock(pairs: &[(&str, &str)]) -> Result<HashMap<String, u32>, ParseIntError> {
    let mut stock = HashMap::new();
    for (title, count) in pairs {
        let n = count.parse::<u32>()?;
        stock.insert(title.to_string(), n);
    }
    Ok(stock)
}

fn main() {
    let good = read_stock(&[("Dune", "3"), ("Emma", "5")]);
    match good {
        Ok(stock) => println!("Dune: {:?}", stock.get("Dune")),
        Err(e) => println!("bad list: {e}"),
    }
    let bad = read_stock(&[("Dune", "3"), ("Emma", "five")]);
    if let Err(e) = bad {
        println!("bad list: {e}");
    }
}

