use std::collections::{HashMap, HashSet};
use std::error::Error;

fn main() -> Result<(), Box<dyn Error>> {
    let log = ["ada 3", "ben 1", "ada 2", "cleo 4", "ben 2"];
    let mut minutes: HashMap<&str, u32> = HashMap::new();
    let mut readers = HashSet::new();
    for line in log {
        let mut parts = line.split_whitespace();
        let name = parts.next().ok_or("missing name")?;
        let mins: u32 = parts.next().ok_or("missing minutes")?.parse()?;
        *minutes.entry(name).or_insert(0) += mins;
        readers.insert(name);
    }
    let mut names = Vec::new();
    for n in &readers {
        names.push(*n);
    }
    names.sort();
    for n in names {
        println!("{n}: {} minutes", minutes[n]);
    }
    Ok(())
}

